exercises.solution:
export function effectiveLatencyUs(hitPermille, hitUs, missUs) {
  const missPermille = 1000 - hitPermille;
  return (hitPermille * hitUs + missPermille * missUs) / 1000;
}

export function missesPerSecond(qps, hitPermille) {
  return (qps * (1000 - hitPermille)) / 1000;
}

