exercises.solution:
export function entriesThatFit(cacheBytes, entryBytes) {
  return Math.floor(cacheBytes / entryBytes);
}

export function evictionsPerHour(cacheBytes, entryBytes, newKeysPerSec) {
  const inserts = newKeysPerSec * 3600;
  return Math.max(0, inserts - entriesThatFit(cacheBytes, entryBytes));
}

