exercises.solution:
export function poolSize(qps, queryMs, headroomPct) {
  // multiply first, divide once: no floating-point dust before Math.ceil
  return Math.ceil((qps * queryMs * (100 + headroomPct)) / 100_000);
}

export function maxInstances(poolPerInstance, dbMaxConnections) {
  return Math.floor(dbMaxConnections / poolPerInstance);
}

