exercises.solution:
export function allowed(limit, arrivals) {
  return Math.min(limit, arrivals);
}

export function requestsRejected(limit, windows) {
  return windows.reduce((sum, arrivals) => sum + (arrivals - allowed(limit, arrivals)), 0);
}

