exercises.solution:
export function tokensAfter(tokens, burst, refillPerSec, elapsedSec) {
  return Math.min(burst, tokens + refillPerSec * elapsedSec);
}

export function canServe(tokens, burst, refillPerSec, elapsedSec, cost) {
  return tokensAfter(tokens, burst, refillPerSec, elapsedSec) >= cost;
}

