exercises.solution:
export function shardCount(totalBytes, bytesPerShard, peakWriteQps, writeQpsPerShard) {
  const forStorage = Math.ceil(totalBytes / bytesPerShard);
  const forWrites = Math.ceil(peakWriteQps / writeQpsPerShard);
  return Math.max(forStorage, forWrites);
}
